<!DOCTYPE html><html><head>    <title></title>    <link rel="stylesheet" type="text/css" href="//apps.bdimg.com/libs/bootstrap/3.3.4/css/bootstrap.css">    <script type="text/javascript" src="//apps.bdimg.com/libs/jquery/2.1.4/jquery.min.js"></script>    <script type="text/javascript" src="{pigcms{$static_public}layer/layer.js"></script>    <link rel="stylesheet" href="{pigcms{$static_public}kindeditor/themes/default/default.css">    <link rel="stylesheet" href="/tpl/System/Static/css/style.css">    <script src="{pigcms{$static_public}kindeditor/kindeditor.js"></script>    <script src="{pigcms{$static_public}kindeditor/lang/zh_CN.js"></script>    <style type="text/css">        .form-inline {            margin-top: 10px;        }        .reward_money_info {            line-height: 25px;            height: 25px;            margin-left: 10px;            padding-left: 10px;        }        .select_msg label {            margin-bottom: 0;        }    </style></head><body><style>	img{		width:100px;		height:50px;	}</style>		<div class="mainbox">			<form name="myform" id="myform" action="" method="post">				<div class="table-list">					<table width="100%" cellspacing="0">						<colgroup><col> <col> <col><col><col><col><col><col width="180" align="center"> </colgroup>						<thead>							<tr>								<th>日期</th>								<th>点击数</th>								<th>曝光数</th>							</tr>						</thead>						<tbody>							<if condition="is_array($list) && $list">								<volist name="list" id="vo">									<tr>										<td>{pigcms{$vo.recording}</td>										<td>{pigcms{$vo.click_num}</td>										<td>{pigcms{$vo.exposure_number}</td>                                    </tr>								</volist>								<tr><td class="textcenter pagebar" colspan="10">{pigcms{$pagebar}</td></tr>							<else/>								<tr><td class="textcenter red" colspan="10">列表为空！</td></tr>							</if>						</tbody>					</table>				</div>			</form>		</div></body></html>